import type { MultiSelectItemsProps } from "../multi-select.types";

import React from "react";
import { clsx } from "clsx";
import { Menu } from "@components/menu";

import { useMultiSelect } from "../hooks/use-multi-select";
import { MultiSelectClasses } from "../multi-select.styles";

import { MultiSelectItem } from "./multi-select-item";

export const MultiSelectItems: React.FC<MultiSelectItemsProps> = ({
  className,
  style,
  children,
  selectAll = "Select all",
  noResults = "No results found",
}) => {
  const {
    filteredOptions,
    pendingValue,
    focusedValue,
    setHasSelectAll,
    hasSelectAll,
    searchValue,
    activeDescendant,
    contentId,
  } = useMultiSelect();

  React.useEffect(() => {
    const showSelectAll = selectAll && !searchValue;
    if (showSelectAll && !hasSelectAll) {
      setHasSelectAll(true);
    }
    if (!showSelectAll && hasSelectAll) {
      setHasSelectAll(false);
    }
  }, [selectAll, hasSelectAll, setHasSelectAll, searchValue]);

  const showSelectAll = selectAll && filteredOptions.length > 1 && !searchValue;

  const renderItems = () => {
    if (filteredOptions.length === 0) {
      return (
        <Menu.Item disabled className={MultiSelectClasses.noResults}>
          {noResults}
        </Menu.Item>
      );
    }

    if (typeof children === "function") {
      return filteredOptions.map((option) =>
        children({
          option,
          isSelected: pendingValue.includes(option.value),
          isFocused: focusedValue === option.value,
        }),
      );
    }

    return filteredOptions.map((option) => (
      <MultiSelectItem key={option.value} value={option.value}>
        {option.label}
      </MultiSelectItem>
    ));
  };

  return (
    <div
      aria-activedescendant={activeDescendant}
      aria-multiselectable="true"
      className={clsx(MultiSelectClasses.items, className)}
      id={contentId}
      role="listbox"
      style={style}
    >
      {showSelectAll && <MultiSelectItem value="select-all">{selectAll}</MultiSelectItem>}
      {renderItems()}
    </div>
  );
};
MultiSelectItems.displayName = "MultiSelect.Items";
